<div class="change-password-panel">
    <button class="panel-toggle" @onclick="() => _expanded = !_expanded">
        @(_expanded ? "▼" : "▶") Change Password
    </button>

    @if (_expanded)
    {
        <div class="panel-content">
            <div class="form-group">
                <label for="currentPassword">Current Password</label>
                <input id="currentPassword" type="password" @bind="CurrentPassword" />
            </div>

            <div class="form-group">
                <label for="newPassword">New Password</label>
                <input id="newPassword" type="password" @bind="NewPassword" />
            </div>

            <div class="form-group">
                <label for="confirmPassword">Confirm Password</label>
                <input id="confirmPassword" type="password" @bind="ConfirmPassword" />
            </div>

            @if (!string.IsNullOrEmpty(_error))
            {
                <p class="error-message">@_error</p>
            }

            @if (_success)
            {
                <p class="success-message">Password updated successfully!</p>
            }

            <button class="btn-primary" @onclick="HandleSubmit">Update Password</button>
        </div>
    }
</div>

@code {
    [Parameter] public EventCallback<(string Current, string New)> OnChangePassword { get; set; }

    private bool _expanded;
    private bool _success;
    private string _error = "";

    private string CurrentPassword { get; set; } = "";
    private string NewPassword { get; set; } = "";
    private string ConfirmPassword { get; set; } = "";

    private async Task HandleSubmit()
    {
        _error = "";
        _success = false;

        if (string.IsNullOrWhiteSpace(CurrentPassword) || string.IsNullOrWhiteSpace(NewPassword))
        {
            _error = "All fields are required.";
            return;
        }

        if (NewPassword != ConfirmPassword)
        {
            _error = "New password and confirmation do not match.";
            return;
        }

        await OnChangePassword.InvokeAsync((CurrentPassword, NewPassword));
        _success = true;
        CurrentPassword = "";
        NewPassword = "";
        ConfirmPassword = "";
    }
}
