toolArgs.file_text:
.settings-page {
    display: flex;
    min-height: calc(100vh - 4rem);
    gap: 0;
}

/* Sidebar */
.settings-sidebar {
    width: 220px;
    background: #f8f9fa;
    border-right: 1px solid #e0e0e0;
    padding: 1rem 0;
}

.settings-sidebar ul {
    list-style: none;
    padding: 0;
    margin: 0;
}

.settings-sidebar li {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.75rem 1.25rem;
    cursor: pointer;
    transition: background 0.2s, border-left 0.2s;
    border-left: 3px solid transparent;
    font-size: 0.95rem;
}

.settings-sidebar li:hover {
    background: #e9ecef;
}

.settings-sidebar li.active {
    background: #e3f2fd;
    border-left-color: #1976d2;
    font-weight: 600;
    color: #1976d2;
}

.sidebar-icon {
    font-size: 1.1rem;
}

/* Content area */
.settings-content {
    flex: 1;
    padding: 2rem;
    max-width: 800px;
}

.settings-section h2 {
    margin-top: 0;
    margin-bottom: 1.5rem;
    font-size: 1.5rem;
    color: #333;
}

.settings-section h3 {
    margin-top: 1.5rem;
    margin-bottom: 0.75rem;
    font-size: 1.1rem;
    color: #555;
}

/* Form elements */
.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.35rem;
    font-weight: 500;
    color: #555;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="password"],
.form-group textarea,
.form-group select {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 0.95rem;
    box-sizing: border-box;
}

.form-group textarea {
    resize: vertical;
}

.form-group select {
    max-width: 300px;
}

/* Buttons */
.form-actions {
    margin-top: 1.5rem;
    display: flex;
    gap: 0.75rem;
}

.btn-primary {
    background: #1976d2;
    color: white;
    border: none;
    padding: 0.5rem 1.25rem;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.9rem;
}

.btn-primary:hover {
    background: #1565c0;
}

.btn-secondary {
    background: #f5f5f5;
    color: #333;
    border: 1px solid #ccc;
    padding: 0.5rem 1.25rem;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.9rem;
}

.btn-secondary:hover {
    background: #e0e0e0;
}

.btn-danger {
    background: #d32f2f;
    color: white;
    border: none;
    padding: 0.5rem 1.25rem;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.9rem;
}

.btn-danger:hover {
    background: #c62828;
}

.btn-sm {
    padding: 0.25rem 0.75rem;
    font-size: 0.8rem;
}

/* Toast */
.toast {
    margin-top: 1rem;
    padding: 0.75rem 1rem;
    border-radius: 4px;
    font-size: 0.9rem;
}

.toast.success {
    background: #e8f5e9;
    color: #2e7d32;
    border: 1px solid #a5d6a7;
}

/* Profile */
.avatar-preview {
    margin-bottom: 1.5rem;
    text-align: center;
}

.avatar-img {
    width: 100px;
    height: 100px;
    border-radius: 50%;
    object-fit: cover;
    border: 3px solid #e0e0e0;
}

.avatar-url {
    font-size: 0.8rem;
    color: #888;
    margin-top: 0.5rem;
    word-break: break-all;
}

/* Toggles */
.toggle-group {
    margin-bottom: 0.75rem;
}

.toggle-label {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    cursor: pointer;
}

.toggle-label input[type="checkbox"] {
    width: 18px;
    height: 18px;
    accent-color: #1976d2;
}

/* Channels */
.channel-list {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    padding-left: 0.25rem;
}

.channel-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    cursor: pointer;
}

/* Radio groups */
.radio-group {
    display: flex;
    gap: 1.5rem;
    margin-top: 0.25rem;
}

.radio-label {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    cursor: pointer;
}

.radio-label input[type="radio"] {
    accent-color: #1976d2;
}

/* Change Password Panel */
.change-password-panel {
    margin-bottom: 1.5rem;
    border: 1px solid #e0e0e0;
    border-radius: 4px;
    overflow: hidden;
}

.panel-toggle {
    width: 100%;
    text-align: left;
    padding: 0.75rem 1rem;
    background: #f8f9fa;
    border: none;
    cursor: pointer;
    font-size: 0.95rem;
    font-weight: 500;
}

.panel-toggle:hover {
    background: #e9ecef;
}

.panel-content {
    padding: 1rem;
    border-top: 1px solid #e0e0e0;
}

.error-message {
    color: #d32f2f;
    font-size: 0.85rem;
    margin: 0.5rem 0;
}

.success-message {
    color: #2e7d32;
    font-size: 0.85rem;
    margin: 0.5rem 0;
}

/* Status indicator */
.status-indicator {
    font-size: 0.8rem;
    padding: 0.2rem 0.5rem;
    border-radius: 12px;
    margin-left: 0.5rem;
}

.status-indicator.enabled {
    background: #e8f5e9;
    color: #2e7d32;
}

.status-indicator.disabled {
    background: #fce4ec;
    color: #c62828;
}

.info-text {
    font-size: 0.85rem;
